def canonicalize_datetime(dt):
    return datetime(dt.year, dt.month, dt.day, tzinfo=pytz.utc)
def get_non_trading_dayslist(non_trading_days, start, end):
    start = int(datetime.strftime(start, '%Y%m%d'))
    end = int(datetime.strftime(end, '%Y%m%d'))
    holiday = data_proxy().get_holiday_local()
    for line in holiday:
        t = line.replace(' ', '').strip()
        if len(t) != 8:
            print('Date format is not correct:' + t)
            continue
        elif not t.isdigit():
            print('Date format is not correct:' + t)
            continue
        elif int(t) >= start and int(t) <= end:
            d = datetime(int(t[0:4]), int(t[4:6]), int(t[6:8]), tzinfo=pytz.utc)
            if d not in non_trading_days:
                non_trading_days.append(d)
    else:
        return non_trading_days
