def get_start_time(end_date=None, count=1):
    if end_date is None:
        end_date = datetime.now().strftime('%Y-%m-%d')
    day = int(count / 240)
    count_minite = count % 240
    if len(end_date) != 12:
        return None
    else:
        end_date_day = end_date[:8]
        end_date_time = end_date[8:12]
        end_date_time_index = minute_list.index(end_date_time)
        start_date_day = end_date_day
        if count_minite > end_date_time_index:
            count_temp = count_minite - end_date_time_index
            start_date_time_index = 240 - (count_temp - 1)
        else:
            start_date_time_index = end_date_time_index - (count_minite - 1)
            if count_minite == 0:
                day -= 1
        start_date_time_index = start_date_time_index % 240
        start_date_time = minute_list[start_date_time_index]
        if start_date_time > end_date_time:
            day_tmp = day + 1
            start_date_day = str(get_trading_day_date(date=end_date_day, day=-day_tmp)).replace('-', '')
        else:
            start_date_day = str(get_trading_day_date(date=end_date_day, day=-day)).replace('-', '')
        start_date = start_date_day + start_date_time
        return start_date
def get_minite_time(end_date=None, count=1):
    if end_date is None:
        end_date = datetime.now().strftime('%Y-%m-%d')
